		secureOptions: undefined,
	},
	encoding: undefined,
	resolveBodyOnly: false,
	isStream: false,
	responseType: 'text',
	url: undefined,
	pagination: {
		transform(response: Response) {
			if (response.request.options.responseType === 'json') {
				return response.body as unknown[];
			}

			const body = response.request.options.responseType === 'buffer'
				? decodeUint8Array(response.body as Uint8Array, response.request.options.encoding)
				: response.body as string;

			return response.request.options.parseJson(body) as unknown[];
		},
		paginate({response}) {
			const rawLinkHeader = response.headers.link;
			if (typeof rawLinkHeader !== 'string' || rawLinkHeader.trim() === '') {
				return false;
			}

			const parsed = parseLinkHeader(rawLinkHeader);
			// The `rel` parameter is a space-separated list of relation types compared case-insensitively. See https://www.rfc-editor.org/rfc/rfc8288#section-3.3
			// Ignore links with an anchor instead of changing their context (RFC 8288, section 3.2).
			const next = parsed.find(entry => !Object.hasOwn(entry.parameters, 'anchor') && entry.parameters.rel?.replaceAll('"', '').toLowerCase().split(/\s+/v).includes('next'));

			if (next) {
				return {
					url: next.reference,
				};
			}

			return false;
		},
		filter: () => true,
		shouldContinue: () => true,
		countLimit: Number.POSITIVE_INFINITY,
		backoff: 0,
		requestLimit: 10_000,
		stackAllItems: false,
	},
	setHost: true,
	maxHeaderSize: undefined,
	signal: undefined,
	enableUnixSockets: false,
	strictContentLength: true,
};

const cloneHeaders = (headers: Headers): Headers => Object.fromEntries(Object.entries(headers).map(([name, value]) => [name, Array.isArray(value) ? [...value] : value]));

// TLS option lists and key/PFX descriptors must not be shared between requests.
const cloneHttps = (https: HttpsOptions): HttpsOptions => Object.fromEntries(Object.entries(https).map(([key, value]) => {
	if (!Array.isArray(value)) {
		return [key, value];
	}

	return [key, value.map(item => is.plainObject(item) ? {...item} : item)];
}));

const cloneInternals = (internals: typeof defaultInternals) => {
	const {hooks, retry} = internals;

	const result: typeof defaultInternals = {
		...internals,
		url: internals.url ? new URL(internals.url) : undefined,
		context: {...internals.context},
		cacheOptions: {...internals.cacheOptions},
		https: cloneHttps(internals.https),
		agent: {...internals.agent},
		headers: cloneHeaders(internals.headers),
		retry: {
			...retry,
			errorCodes: [...retry.errorCodes!],
			methods: [...retry.methods!],
			statusCodes: [...retry.statusCodes!],
		},
		timeout: {...internals.timeout},
		hooks: {
			init: [...hooks.init],
			beforeRequest: [...hooks.beforeRequest],
			beforeError: [...hooks.beforeError],
			beforeRedirect: [...hooks.beforeRedirect],
			beforeRetry: [...hooks.beforeRetry],
			beforeCache: [...hooks.beforeCache],
			afterResponse: [...hooks.afterResponse],
		},
		searchParams: internals.searchParams ? new URLSearchParams(internals.searchParams as URLSearchParams) : undefined,
		pagination: {...internals.pagination},
	};

	return result;
};

const cloneRaw = (raw: OptionsInit) => {
	const result: OptionsInit = {...raw};

	if (Object.hasOwn(raw, 'context') && is.object(raw.context)) {
		result.context = {...raw.context};
	}

	if (Object.hasOwn(raw, 'cacheOptions') && is.object(raw.cacheOptions)) {
		result.cacheOptions = {...raw.cacheOptions};
	}

	if (Object.hasOwn(raw, 'https') && is.object(raw.https)) {
		result.https = cloneHttps(raw.https);
	}

	if (Object.hasOwn(raw, 'agent') && is.object(raw.agent)) {
		result.agent = {...raw.agent};
	}

	if (Object.hasOwn(raw, 'headers') && is.object(raw.headers)) {
		result.headers = cloneHeaders(raw.headers);
	}

	if (Object.hasOwn(raw, 'retry') && is.object(raw.retry)) {
		const {retry} = raw;
		result.retry = {...retry};

		if (is.array(retry.errorCodes)) {
			result.retry.errorCodes = [...retry.errorCodes];
		}

		if (is.array(retry.methods)) {
			result.retry.methods = [...retry.methods];
		}

		if (is.array(retry.statusCodes)) {
			result.retry.statusCodes = [...retry.statusCodes];
		}
	}

	if (Object.hasOwn(raw, 'timeout') && is.object(raw.timeout)) {
		result.timeout = {...raw.timeout};
	}

	if (Object.hasOwn(raw, 'hooks') && is.object(raw.hooks)) {
		const {hooks} = raw;
		result.hooks = {
			...hooks,
		};

		if (is.array(hooks.init)) {
			result.hooks.init = [...hooks.init];
		}

		if (is.array(hooks.beforeRequest)) {
			result.hooks.beforeRequest = [...hooks.beforeRequest];
		}

		if (is.array(hooks.beforeError)) {
			result.hooks.beforeError = [...hooks.beforeError];
		}

		if (is.array(hooks.beforeRedirect)) {
			result.hooks.beforeRedirect = [...hooks.beforeRedirect];
		}

		if (is.array(hooks.beforeRetry)) {
			result.hooks.beforeRetry = [...hooks.beforeRetry];
		}

		if (is.array(hooks.beforeCache)) {
			result.hooks.beforeCache = [...hooks.beforeCache];
		}

		if (is.array(hooks.afterResponse)) {
			result.hooks.afterResponse = [...hooks.afterResponse];
		}
	}

	if (Object.hasOwn(raw, 'searchParams') && raw.searchParams) {
		if (is.string(raw.searchParams)) {
			result.searchParams = raw.searchParams;
		} else if (raw.searchParams instanceof URLSearchParams) {
			result.searchParams = new URLSearchParams(raw.searchParams);
		} else if (is.object(raw.searchParams)) {
			result.searchParams = {...raw.searchParams};
		}
	}

	if (Object.hasOwn(raw, 'pagination') && is.object(raw.pagination)) {
		result.pagination = {...raw.pagination};
	}

	return result;
};

const getHttp2TimeoutOption = (internals: typeof defaultInternals): number | undefined => {
	const delays = [
		internals.timeout.connect,
		internals.timeout.lookup,
		internals.timeout.request,
		internals.timeout.secureConnect,
	].filter(delay => typeof delay === 'number');

	return delays.length > 0 ? Math.min(...delays) : undefined;
};

const usesHttp2Alpn = (internals: typeof defaultInternals, url: URL): boolean => {
	const usesCustomHttpsAgent = internals.agent.https !== undefined
		&& internals.agent.https !== false
		&& internals.createConnection === undefined;

	return internals.http2
		&& url.protocol === 'https:'
		&& !internals.h2session
		&& !usesCustomHttpsAgent;
};

const trackStateMutation = (trackedStateMutations: Set<string> | undefined, name: string): void => {
	trackedStateMutations?.add(name);
};

const addExplicitHeader = (explicitHeaders: Set<string>, name: string): void => {
	explicitHeaders.add(name);
};

const markHeaderAsExplicit = (explicitHeaders: Set<string>, trackedStateMutations: Set<string> | undefined, name: string): void => {
	addExplicitHeader(explicitHeaders, name);
	trackStateMutation(trackedStateMutations, name);
};

const trackReplacedHeaderMutations = (trackedStateMutations: Set<string> | undefined, previousHeaders: Headers, nextHeaders: Headers): void => {
	if (!trackedStateMutations) {
		return;
	}

	for (const header of new Set([...Object.keys(previousHeaders), ...Object.keys(nextHeaders)])) {
		if (previousHeaders[header] !== nextHeaders[header]) {
			trackStateMutation(trackedStateMutations, header);
		}
	}
};

const init = (options: OptionsInit, withOptions: OptionsInit, self: Options): void => {
	const initHooks = options.hooks?.init;
	if (initHooks) {
		for (const hook of initHooks) {
			hook(withOptions, self);
		}
	}
};

// Keys never merged: got.extend() internals, url (passed as first arg), control flags, security
const nonMergeableKeys: ReadonlySet<string> = new Set(['mutableDefaults', 'handlers', 'url', 'preserveHooks', 'isStream', '__proto__']);
// Options where an explicit `undefined` resets the inherited value instead of keeping it.
const resettableByUndefined: ReadonlySet<string> = new Set(['searchParams', 'cookieJar']);

// Whether the options supply a body, JSON, or form payload explicitly.
const hasExplicitBodyOption = (options: OptionsInit): boolean =>
	(Object.hasOwn(options, 'body') && options.body !== undefined)
	|| (Object.hasOwn(options, 'json') && options.json !== undefined)
	|| (Object.hasOwn(options, 'form') && options.form !== undefined);

export default class Options {
	readonly #internals: InternalsType;
	#headersProxy: Headers;
	#merging = false;
	readonly #init: OptionsInit[];
	readonly #explicitHeaders: Set<string>;
	#trackedStateMutations?: Set<string>;

	constructor(input?: string | URL | OptionsInit, options?: OptionsInit, defaults?: Options) {
		assertAny('input', [is.string, is.urlInstance, is.object, is.undefined], input);
		assertAny('options', [is.object, is.undefined], options);
		assertAny('defaults', [is.object, is.undefined], defaults);

		if (input instanceof Options || options instanceof Options) {
			throw new TypeError('The defaults must be passed as the third argument');
		}

		if (defaults) {
			this.#internals = cloneInternals(defaults.#internals);
			this.#init = [...defaults.#init];
			this.#explicitHeaders = new Set(defaults.#explicitHeaders);
		} else {
			this.#internals = cloneInternals(defaultInternals);
			this.#init = [];
			this.#explicitHeaders = new Set();
		}

		this.#headersProxy = this.#createHeadersProxy();

		// This rule allows `finally` to be considered more important.
		// Meaning no matter the error thrown in the `try` block,
		// if `finally` throws then the `finally` error will be thrown.
		//
		// Yes, we want this. If we set `url` first, then the `url.searchParams`
		// would get merged. Instead we set the `searchParams` first, then
		// `url.searchParams` is overwritten as expected.
		//
		/* eslint-disable no-unsafe-finally -- `finally` is used intentionally here to ensure `url` is always set last, overwriting any merged searchParams */
		try {
			if (is.plainObject(input)) {
				try {
					this.merge(input);
					this.merge(options);
				} finally {
					this.url = input.url;
				}
			} else {
				try {
					this.merge(options);
				} finally {
					if (options?.url !== undefined) {
						if (input === undefined) {
							this.url = options.url;
						} else {
							throw new TypeError('The `url` option is mutually exclusive with the `input` argument');
						}
					} else if (input !== undefined) {
						this.url = input;
					}
				}
			}
		} catch (error) {
			const optionsError = normalizeError(error) as OptionsError;
			optionsError.options = this;

			throw optionsError;
